package com.cpf.batch.runtime; import com.cpf.batch.api.RuntimeRegistration; import org.springframework.boot.autoconfigure.condition.ConditionalOnMissingBean; import org.springframework.context.annotation.*; import org.springframework.scheduling.annotation.EnableScheduling; import org.springframework.web.client.RestClient;
@Configuration @EnableScheduling @Import(DefaultBusinessCalendarConfiguration.class) public class RuntimeCommonConfiguration { @Bean @ConditionalOnMissingBean RuntimeStateProvider runtimeStateProvider(){return new RuntimeStateProvider(){};} @Bean RuntimeSmokeController runtimeSmokeController(RuntimeRegistration r,RuntimeStateProvider s){return new RuntimeSmokeController(r,s);}
 @Bean RuntimeReporter runtimeReporter(RuntimeRegistration r,RuntimeStateProvider s,RestClient.Builder b){return new RuntimeReporter(r,s,b,System.getenv().getOrDefault("CPF_BATCH_CONTROL_BASE_URL","http://127.0.0.1:8180"));} @Bean JobPackCatalog jobPackCatalog(){return new JobPackCatalog();} }
